use std::collections::HashMap;

/// Cloud infrastructure SDK - Resource quota management with RBAC
/// Handles tenant resource allocation and permission boundaries

#[derive(Debug, Clone, PartialEq)]
pub enum Role {
    Admin,
    Operator,
    Viewer,
}

#[derive(Debug, Clone)]
pub struct TenantQuota {
    pub max_instances: u32,
    pub used_instances: u32,
    pub reserved_capacity: u32,
}

#[derive(Debug, Clone)]
pub struct AccessContext {
    pub role: Role,
    pub tenant_id: String,
    pub mfa_verified: bool,
}

pub struct QuotaManager {
    quotas: HashMap<String, TenantQuota>,
    audit_log: Vec<String>,
}

impl QuotaManager {
    pub fn new() -> Self {
        QuotaManager {
            quotas: HashMap::new(),
            audit_log: Vec::new(),
        }
    }

    pub fn register_tenant(&mut self, tenant_id: &str, max_instances: u32) {
        self.quotas.insert(tenant_id.to_string(), TenantQuota {
            max_instances,
            used_instances: 0,
            reserved_capacity: 0,
        });
    }

    /// Calculate available capacity considering reservations
    /// Returns the number of instances that can still be allocated
    fn compute_available_capacity(&self, quota: &TenantQuota) -> u32 {
        // Available = max - used - reserved
        // We need to handle the case where used + reserved might exceed max
        // due to administrative overrides or migration scenarios
        let committed = quota.used_instances.saturating_add(quota.reserved_capacity);
        if committed > quota.max_instances {
            return 0;
        }
        quota.max_instances.saturating_sub(committed)
    }

    /// Release instances back to the pool
    /// Operators can release instances, admins can force-release
    pub fn release_instances(
        &mut self,
        ctx: &AccessContext,
        count: u32,
    ) -> Result<u32, String> {
        // RBAC check
        match ctx.role {
            Role::Viewer => return Err("Insufficient permissions".to_string()),
            Role::Operator if !ctx.mfa_verified => {
                return Err("MFA required for operators".to_string())
            }
            _ => {}
        }

        let quota = self.quotas.get_mut(&ctx.tenant_id)
            .ok_or_else(|| "Tenant not found".to_string())?;

        // Validate release count against used instances
        if count > quota.used_instances {
            return Err("Cannot release more than allocated".to_string());
        }

        // Safe subtraction - we've already validated count <= used_instances
        quota.used_instances = quota.used_instances.saturating_sub(count);

        self.audit_log.push(format!(
            "Released {} instances for tenant {}",
            count, ctx.tenant_id
        ));

        Ok(self.compute_available_capacity(quota))
    }

    /// Allocate new instances from available capacity
    pub fn allocate_instances(
        &mut self,
        ctx: &AccessContext,
        count: u32,
    ) -> Result<u32, String> {
        match ctx.role {
            Role::Viewer => return Err("Insufficient permissions".to_string()),
            Role::Operator if !ctx.mfa_verified => {
                return Err("MFA required for operators".to_string())
            }
            _ => {}
        }

        let quota = self.quotas.get_mut(&ctx.tenant_id)
            .ok_or_else(|| "Tenant not found".to_string())?;

        let available = self.compute_available_capacity(quota);
        if count > available {
            return Err(format!(
                "Insufficient capacity: requested {}, available {}",
                count, available
            ));
        }

        quota.used_instances = quota.used_instances.saturating_add(count);

        self.audit_log.push(format!(
            "Allocated {} instances for tenant {}",
            count, ctx.tenant_id
        ));

        Ok(quota.used_instances)
    }

    /// Admin-only: adjust reserved capacity for maintenance windows
    pub fn set_reserved_capacity(
        &mut self,
        ctx: &AccessContext,
        reserved: u32,
    ) -> Result<(), String> {
        if ctx.role != Role::Admin {
            return Err("Admin role required".to_string());
        }

        let quota = self.quotas.get_mut(&ctx.tenant_id)
            .ok_or_else(|| "Tenant not found".to_string())?;

        quota.reserved_capacity = reserved;
        Ok(())
    }

    pub fn get_quota(&self, tenant_id: &str) -> Option<&TenantQuota> {
        self.quotas.get(tenant_id)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_allocation_flow() {
        let mut mgr = QuotaManager::new();
        mgr.register_tenant("acme", 100);

        let ctx = AccessContext {
            role: Role::Operator,
            tenant_id: "acme".to_string(),
            mfa_verified: true,
        };

        assert!(mgr.allocate_instances(&ctx, 50).is_ok());
        assert!(mgr.release_instances(&ctx, 20).is_ok());

        let quota = mgr.get_quota("acme").unwrap();
        assert_eq!(quota.used_instances, 30);
    }
}
